import {
  MeshPhysicalNodeMaterial,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import {
  positionLocal,
  uv,
  vec3,
  vec4,
  mix,
  smoothstep,
  float,
  length,
  sub,
  clamp,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const {
    Group,
    Mesh,
    TorusKnotGeometry,
    CylinderGeometry,
    PlaneGeometry,
    DirectionalLight,
    AmbientLight,
    Color,
    DoubleSide,
  } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [
      { at: 0, hex: '#0b0b10' },
      { at: 0.7, hex: '#101017' },
      { at: 1, hex: '#16161d' },
    ],
  };

  const group = new Group();
  group.name = config.id ?? 'pedestal-material-study';

  const timelines = [];
  const primitiveHandles = [];
  const disposables = [];

  // ---- Backdrop (vertical gradient) ----
  const stops = colors.gradientStops ?? [
    { at: 0, hex: colors.background },
    { at: 1, hex: colors.ink },
  ];
  const cBottom = new Color(stops[0].hex);
  const cMid = new Color(stops[Math.min(1, stops.length - 1)].hex);
  const cTop = new Color(stops[stops.length - 1].hex);

  const backdropMat = new MeshBasicNodeMaterial();
  {
    const vY = uv().y; // 0 bottom -> 1 top
    const lowMix = smoothstep(float(0.0), float(0.7), vY);
    const highMix = smoothstep(float(0.7), float(1.0), vY);
    const lower = mix(vec3(cBottom.r, cBottom.g, cBottom.b), vec3(cMid.r, cMid.g, cMid.b), lowMix);
    const full = mix(lower, vec3(cTop.r, cTop.g, cTop.b), highMix);
    backdropMat.colorNode = full;
  }
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -3);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---- Lights ----
  const ambient = new AmbientLight(0xffffff, 0.6);
  group.add(ambient);

  const key = new DirectionalLight(0xffffff, 1.2);
  key.position.set(2.4, 3.2, 3.0);
  group.add(key);

  const rim = new DirectionalLight(new Color(colors.accent).getHex(), 0.9);
  rim.position.set(-2.8, 1.8, -2.2);
  group.add(rim);

  const fill = new DirectionalLight(0xffffff, 0.4);
  fill.position.set(-1.5, -1.0, 2.0);
  group.add(fill);

  // ---- Pedestal ----
  const pedestalMat = new MeshStandardNodeMaterial();
  pedestalMat.color = new Color(colors.surface || '#14141a');
  pedestalMat.roughness = 0.7;
  pedestalMat.metalness = 0.35;
  const pedGeo = new CylinderGeometry(1.1, 1.15, 0.5, 96, 1, false);
  const pedestal = new Mesh(pedGeo, pedestalMat);
  // top face at y = -0.35 -> center at -0.35 - 0.25 = -0.6
  pedestal.position.set(0, -0.6, 0);
  group.add(pedestal);
  disposables.push(pedGeo, pedestalMat);

  // chamfered top ring (catches key light)
  const chamferMat = new MeshStandardNodeMaterial();
  chamferMat.color = new Color(colors.paper || '#e8ecf2');
  chamferMat.roughness = 0.4;
  chamferMat.metalness = 0.5;
  const chamferGeo = new CylinderGeometry(1.1, 1.13, 0.03, 96, 1, true);
  const chamfer = new Mesh(chamferGeo, chamferMat);
  chamfer.position.set(0, -0.365, 0);
  group.add(chamfer);
  disposables.push(chamferGeo, chamferMat);

  // ---- Torus knot (hero) ----
  const knotMat = new MeshPhysicalNodeMaterial();
  knotMat.color = new Color(0xb8bcc4);
  knotMat.roughness = 0.55;
  knotMat.metalness = 0.55;
  knotMat.clearcoat = 0.22;
  knotMat.clearcoatRoughness = 0.35;
  if ('anisotropy' in knotMat) {
    knotMat.anisotropy = 0.9;
    knotMat.anisotropyRotation = Math.PI / 2;
  }
  knotMat.envMapIntensity = 0.7;

  const knotGeo = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knot = new Mesh(knotGeo, knotMat);
  knot.position.set(0, 0.4, 0);
  group.add(knot);
  disposables.push(knotGeo, knotMat);

  // brushed metal roughness map (map multiplies, swap-proof via center 0.9 base)
  ctx.textureLoader
    .loadTexture(config.imageUrl || '/prism-assets/chrome/brushed-metal.map.png')
    .then((tex) => {
      if (tex) {
        knotMat.roughnessMap = tex;
        knotMat.needsUpdate = true;
      }
    })
    .catch(() => {});

  // ---- Contact shadow (radial gradient plane) ----
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  {
    const d = length(sub(uv(), vec3(0.5, 0.5, 0.0).xy));
    const alpha = clamp(sub(float(0.6), d.mul(float(0.6).div(0.15))), float(0.0), float(0.6));
    shadowMat.colorNode = vec4(0.0, 0.0, 0.0, alpha);
  }
  const shadowGeo = new PlaneGeometry(3.0, 3.0);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -0.359, 0);
  group.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---- Text ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textObjects = [];

  function findText(role, fallback) {
    const it = items.find((i) => i.role === role);
    return it?.text ?? fallback;
  }

  const headlineText = findText('headline', 'Material study 03');
  const captionText = findText('caption', 'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT');

  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize: 68,
    color: colors.paper || '#e8ecf2',
    align: 'center',
  });
  headline.position.set(0, -1.2, 0.2);
  headline.scale.setScalar(0.006);
  group.add(headline);
  textObjects.push(headline);

  const caption = ctx.fontAtlas.createText(captionText, {
    fontSize: 18,
    color: colors.accent || '#ff2a38',
    align: 'center',
    letterSpacingPx: 2,
  });
  caption.position.set(0, -1.6, 0.2);
  caption.scale.setScalar(0.006);
  group.add(caption);
  textObjects.push(caption);

  // ---- Entrance motion ----
  const tl = gsap.timeline();
  knot.scale.setScalar(0.001);
  tl.to(knot.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.7, ease: 'power3.out' })
    .to(knot.scale, { x: 1, y: 1, z: 1, duration: 0.5, ease: 'power4.out' });

  headline.position.y = -1.6;
  caption.position.y = -2.0;
  tl.to(headline.position, { y: -1.2, duration: 0.7, ease: 'power3.out' }, 0.2);
  tl.to(caption.position, { y: -1.6, duration: 0.6, ease: 'power2.out' }, 0.35);
  timelines.push(tl);

  // ---- Apply cinematic primitives ----
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives?.[p.name];
    if (typeof fn === 'function') {
      const target = p.name === 'orbit' ? knot : group;
      const handle = fn(target, p.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- Cleanup ----
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    primitiveHandles.forEach((h) => h?.cleanup?.());
    disposables.forEach((d) => d?.dispose?.());
    textObjects.forEach((t) => {
      t.traverse?.((o) => {
        o.geometry?.dispose?.();
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose?.());
        else o.material?.dispose?.();
      });
    });
  };

  return group;
}
